package vvlib

// Reference cases (PLAN.md D13, 3.10, 4.4, 5.7): graphs written by hand against
// the library, each with the arguments and labels it must produce. The
// expectations are never generated by the code under test.
//
// A case file holds a list of cases:
//
//	cases:
//	  - name: ad_hominem/positive
//	    source: "42, p. 336"                      # where the reading comes from
//	    schemes: [ad_hominem]                     # optional live-library rule selection
//	    library: walton.yml                       # the scheme file loaded (default walton.yml)
//	    graph: |                                  # or a whole graph file of its own, instead
//	      ...
//	    assumptions: [bad_character(bob), ...]    # one term per line in practice
//	    questioned: [...]                         # statements called into question
//	    arguments: ["ad_hominem(bob,arg1,tax_cut)"]  # built, scheme(parameters)
//	    no_arguments: [ad_hominem]               # no argument of these schemes (or scheme(parameters))
//	    in: [...]                                 # labelled in
//	    not_in: [...]                             # out or undecided (or absent)
//	    out: [...]                                # labelled out
//	    issues: [[h, ¬h]]                         # an issue with exactly these positions
//	    outcome: invalid input                    # Infer ends this way (default: complete)
//	    variants: true                            # each assumption needed, each exception undercuts
//	    exact_schemes: [practical_reasoning_as2]  # the arguments listed are all those of these schemes
//
// practical_as2.yml is written by tools/aats.py from the models of
// tools/aats_models: its expectations come from that adapter, which is
// validated against the paper on its own (tools/test_aats.py), not from the
// engine or the library under test.
//
// Each case is one check, "case", of the case file.

import (
	"bytes"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"reflect"
	"sort"
	"strings"

	"github.com/carneades/carneades-4/src/engine/caes"
	cyaml "github.com/carneades/carneades-4/src/engine/caes/encoding/yaml"
	"github.com/carneades/carneades-4/src/engine/terms"
	"gopkg.in/yaml.v2"
)

// Case is one reference case.
type Case struct {
	Name        string     `yaml:"name"`
	Source      string     `yaml:"source"`
	Library     string     `yaml:"library"`
	Schemes     []string   `yaml:"schemes"`
	Graph       string     `yaml:"graph"`
	Assumptions []string   `yaml:"assumptions"`
	Questioned  []string   `yaml:"questioned"`
	Arguments   []string   `yaml:"arguments"`
	NoArguments []string   `yaml:"no_arguments"`
	In          []string   `yaml:"in"`
	NotIn       []string   `yaml:"not_in"`
	Out         []string   `yaml:"out"`
	Issues      [][]string `yaml:"issues"`
	Outcome     string     `yaml:"outcome"`
	// Variants, for a case with one argument (PLAN.md 5.7): leaving out any
	// one assumption of the case builds no such argument with the selected
	// schema isolated; the ordinary positive case retains its declared theory
	// context (the whole library unless Schemes is explicitly supplied).
	// Stating any
	// one exception of its scheme, for the argument's parameters, undercuts
	// it.
	Variants bool `yaml:"variants"`
	// ExactSchemes: for each scheme listed, the arguments the engine builds
	// with it are exactly those of Arguments that name it, no more.
	ExactSchemes []string `yaml:"exact_schemes"`
}

// CaseFiles lists the case files under tools/vv/cases.
func CaseFiles() []string {
	files, _ := filepath.Glob(filepath.Join("cases", "*.yml"))
	sort.Strings(files)
	return files
}

// LoadCases reads a case file.
func LoadCases(path string) ([]Case, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	var f struct {
		Cases []Case `yaml:"cases"`
	}
	if err := yaml.UnmarshalStrict(data, &f); err != nil {
		return nil, err
	}
	return f.Cases, nil
}

var outcomes = map[string]error{
	"invalid input":        caes.ErrInvalidInput,
	"unsupported":          caes.ErrUnsupported,
	"inconsistent context": caes.ErrInconsistentContext,
	"limit reached":        caes.ErrLimitReached,
}

// selectCaseSchemes retains actual imported records and rebuilds the private
// index from scratch. A nil selection means all rules; an explicit empty list
// means none. Issue schemes and language retain the case's declared context.
func selectCaseSchemes(ag *caes.ArgGraph, ids []string) error {
	if ids == nil {
		return nil
	}
	byID := map[string]*caes.Scheme{}
	for _, s := range ag.Theory.ArgSchemes {
		if _, duplicate := byID[s.Id]; duplicate {
			return fmt.Errorf("duplicate library scheme %s", s.Id)
		}
		byID[s.Id] = s
	}
	selected := caes.NewTheory()
	selected.Language = ag.Theory.Language
	selected.WeighingFunctions = ag.Theory.WeighingFunctions
	selected.WeighingSpecs = ag.Theory.WeighingSpecs
	selected.IssueSchemes = ag.Theory.IssueSchemes
	seen := map[string]bool{}
	for _, id := range ids {
		if seen[id] {
			return fmt.Errorf("duplicate selected scheme %s", id)
		}
		seen[id] = true
		s, ok := byID[id]
		if !ok {
			return fmt.Errorf("unknown selected scheme %s", id)
		}
		selected.ArgSchemes = append(selected.ArgSchemes, s)
	}
	selected.InitSchemeIndex()
	ag.Theory = selected
	return nil
}

func importCase(data []byte, c Case) (*caes.ArgGraph, error) {
	ag, err := cyaml.Import(strings.NewReader(string(data)))
	if err != nil {
		return nil, err
	}
	if err := selectCaseSchemes(ag, c.Schemes); err != nil {
		return nil, err
	}
	for _, fact := range c.Assumptions {
		ag.AddAssumption(fact)
	}
	ag.Questioned = append(ag.Questioned, c.Questioned...)
	return ag, nil
}

// A shared observation-only oracle: importing or checking CLI output must not
// infer again and repair the very result the case is meant to judge.
type caseObservation struct {
	labels    map[string]string
	arguments map[string]bool
	schemes   map[string]bool
	issues    [][]string
}

func newCaseObservation() caseObservation {
	return caseObservation{labels: map[string]string{}, arguments: map[string]bool{}, schemes: map[string]bool{}}
}

func (o *caseObservation) argument(scheme string, parameters []string) {
	o.schemes[scheme] = true
	o.arguments[terms.Normalize(scheme+"("+strings.Join(parameters, ",")+")")] = true
}

func observeCaseGraph(ag *caes.ArgGraph, l caes.Labelling) caseObservation {
	o := newCaseObservation()
	for id, s := range ag.Statements {
		o.labels[terms.Normalize(id)] = l[s].String()
	}
	for _, a := range ag.Arguments {
		if a != nil {
			scheme := "linked"
			if a.Scheme != nil {
				scheme = a.Scheme.Id
			}
			o.argument(scheme, a.Parameters)
		}
	}
	for _, is := range ag.Issues {
		positions := []string{}
		for _, p := range is.Positions {
			positions = append(positions, terms.Normalize(p.Id))
		}
		o.issues = append(o.issues, positions)
	}
	return o
}

func observeCaseYAML(text string) (caseObservation, error) {
	o := newCaseObservation()
	observedLabels, err := labels(text)
	if err != nil {
		return o, err
	}
	for id, label := range observedLabels {
		o.labels[terms.Normalize(id)] = label
	}
	var d struct {
		Arguments map[string]struct {
			Scheme     string   `yaml:"scheme"`
			Parameters []string `yaml:"parameters"`
		} `yaml:"arguments"`
		Issues map[string]struct {
			Positions []string `yaml:"positions"`
		} `yaml:"issues"`
	}
	if err := yaml.Unmarshal([]byte(text), &d); err != nil {
		return o, err
	}
	for _, a := range d.Arguments {
		// The graph format's default scheme for authored arguments is linked.
		if a.Scheme == "" {
			a.Scheme = "linked"
		}
		o.argument(a.Scheme, a.Parameters)
	}
	for _, is := range d.Issues {
		positions := []string{}
		for _, p := range is.Positions {
			positions = append(positions, terms.Normalize(p))
		}
		o.issues = append(o.issues, positions)
	}
	return o, nil
}

func caseExpectationProblems(c Case, o caseObservation) []string {
	label := func(id string) string {
		v, ok := o.labels[terms.Normalize(id)]
		if !ok {
			return "absent"
		}
		return v
	}
	var probs []string
	for _, a := range c.Arguments {
		if !o.arguments[terms.Normalize(a)] {
			probs = append(probs, "no argument "+a)
		}
	}
	for _, scheme := range c.ExactSchemes {
		want := map[string]bool{}
		for _, a := range c.Arguments {
			if strings.HasPrefix(a, scheme+"(") {
				want[terms.Normalize(a)] = true
			}
		}
		extra := []string{}
		for a := range o.arguments {
			if strings.HasPrefix(a, scheme+"(") && !want[a] {
				extra = append(extra, a)
			}
		}
		sort.Strings(extra)
		for _, a := range extra {
			probs = append(probs, "an argument "+a+" was built, but the case lists every argument of "+scheme)
		}
	}
	for _, a := range c.NoArguments {
		if strings.Contains(a, "(") {
			if o.arguments[terms.Normalize(a)] {
				probs = append(probs, "an argument "+a+" was built")
			}
		} else if o.schemes[a] {
			probs = append(probs, "an argument of "+a+" was built")
		}
	}
	for _, s := range c.In {
		if got := label(s); got != "in" {
			probs = append(probs, fmt.Sprintf("%s is %s, want in", s, got))
		}
	}
	for _, s := range c.Out {
		if got := label(s); got != "out" {
			probs = append(probs, fmt.Sprintf("%s is %s, want out", s, got))
		}
	}
	for _, s := range c.NotIn {
		if got := label(s); got == "in" {
			probs = append(probs, fmt.Sprintf("%s is in, want not in", s))
		}
	}
	for _, want := range c.Issues {
		found := false
		for _, positions := range o.issues {
			got := append([]string{}, positions...)
			w := []string{}
			for _, p := range want {
				w = append(w, terms.Normalize(p))
			}
			sort.Strings(got)
			sort.Strings(w)
			if reflect.DeepEqual(got, w) {
				found = true
			}
		}
		if !found {
			probs = append(probs, fmt.Sprintf("no issue with the positions %v", want))
		}
	}
	return probs
}

// RunCase evaluates one case and returns its problems.
func RunCase(root string, c Case) []string {
	lib := c.Library
	if lib == "" {
		lib = "walton.yml"
	}
	var data []byte
	var err error
	if c.Graph != "" {
		data = []byte(c.Graph)
	} else if data, err = os.ReadFile(filepath.Join(root, lib)); err != nil {
		return []string{err.Error()}
	}
	ResetEngineGlobals()
	cap := StartCapture()
	defer func() { cap.Stop(); ResetEngineGlobals() }()
	ag, err := importCase(data, c)
	if err != nil {
		return []string{"the graph does not import: " + err.Error()}
	}
	err = ag.Infer()
	if c.Outcome != "" {
		want, ok := outcomes[c.Outcome]
		if !ok {
			return []string{"unknown outcome " + c.Outcome}
		}
		if !errors.Is(err, want) {
			return []string{fmt.Sprintf("Infer: want %s, got %v", c.Outcome, err)}
		}
		return nil
	}
	if err != nil {
		return []string{"Infer: " + err.Error()}
	}
	probs := caseExpectationProblems(c, observeCaseGraph(ag, ag.GroundedLabelling()))
	if c.Variants {
		probs = append(probs, variantProblems(data, c)...)
	}
	return probs
}

// variantProblems isolates the selected current scheme for its positive control
// and premise withdrawals. The normal case and exception checks retain the
// case's declared theory context, where another selected scheme may legitimately
// rederive a withdrawn fact.
func variantProblems(data []byte, c Case) []string {
	if len(c.Arguments) != 1 {
		return []string{"variants need exactly one argument"}
	}
	t, ok := parse(c.Arguments[0])
	call, isC := t.(terms.Compound)
	if !ok || !isC {
		return []string{"variants: the argument is not scheme(parameters)"}
	}
	run := func(assumptions []string, isolate bool) (*caes.ArgGraph, caes.Labelling, *caes.Scheme, error) {
		ResetEngineGlobals()
		cap := StartCapture()
		defer func() { cap.Stop(); ResetEngineGlobals() }()
		ag, err := cyaml.Import(strings.NewReader(string(data)))
		if err != nil {
			return nil, nil, nil, err
		}
		if err := selectCaseSchemes(ag, c.Schemes); err != nil {
			return nil, nil, nil, err
		}
		var s *caes.Scheme
		for _, x := range ag.Theory.ArgSchemes {
			if x.Id == call.Functor {
				s = x
			}
		}
		if s == nil {
			return nil, nil, nil, fmt.Errorf("the selected scheme %s is not in the graph", call.Functor)
		}
		if isolate {
			if err := selectCaseSchemes(ag, []string{s.Id}); err != nil {
				return nil, nil, nil, err
			}
		}
		for _, fact := range assumptions {
			ag.AddAssumption(fact)
		}
		ag.Questioned = append(ag.Questioned, c.Questioned...)
		if err := ag.Infer(); err != nil {
			return ag, nil, s, err
		}
		return ag, ag.GroundedLabelling(), s, nil
	}
	find := func(ag *caes.ArgGraph) *caes.Argument {
		for _, a := range ag.Arguments {
			if a != nil && a.Scheme != nil && terms.Normalize(a.Scheme.Id+"("+strings.Join(a.Parameters, ",")+")") == terms.Normalize(c.Arguments[0]) {
				return a
			}
		}
		return nil
	}
	probs := []string{}
	plain, _, _, err := run(c.Assumptions, true)
	if err != nil || find(plain) == nil {
		return []string{fmt.Sprintf("variants: isolated positive control does not build %s (%v)", c.Arguments[0], err)}
	}
	for i := range c.Assumptions {
		rest := append(append([]string{}, c.Assumptions[:i]...), c.Assumptions[i+1:]...)
		ag, _, _, err := run(rest, true)
		if err != nil {
			probs = append(probs, fmt.Sprintf("without %s: %v", c.Assumptions[i], err))
		} else if find(ag) != nil {
			probs = append(probs, fmt.Sprintf("without %s the argument is still built", c.Assumptions[i]))
		}
	}
	_, _, s, err := run(c.Assumptions, false)
	if err != nil || s == nil {
		return append(probs, fmt.Sprintf("variants: the scheme %s is not in the graph (%v)", call.Functor, err))
	}
	if len(s.Variables) != len(call.Args) {
		return append(probs, fmt.Sprintf("variants: %s has %d variables, the argument %d parameters", s.Id, len(s.Variables), len(call.Args)))
	}
	bind := map[string]terms.Term{}
	for i, v := range s.Variables {
		bind[v] = call.Args[i]
	}
	var subst func(t terms.Term) terms.Term
	subst = func(t terms.Term) terms.Term {
		switch v := t.(type) {
		case terms.Variable:
			if b, ok := bind[v.Name]; ok {
				return b
			}
		case terms.Compound:
			args := make([]terms.Term, len(v.Args))
			for i, a := range v.Args {
				args[i] = subst(a)
			}
			return terms.Compound{Functor: v.Functor, Args: args}
		}
		return t
	}
	for _, e := range s.Exceptions {
		et, ok := parse(e)
		if !ok {
			probs = append(probs, "variants: cannot read the exception "+e)
			continue
		}
		stated := subst(et).String()
		ag, l, _, err := run(append(append([]string{}, c.Assumptions...), stated), false)
		if err != nil {
			probs = append(probs, fmt.Sprintf("with %s: %v", stated, err))
			continue
		}
		a := find(ag)
		if a == nil || a.Undercutter == nil {
			probs = append(probs, fmt.Sprintf("with %s the argument is not built", stated))
		} else if l[a.Undercutter] != caes.In {
			probs = append(probs, fmt.Sprintf("with %s the argument is not undercut", stated))
		}
	}
	return probs
}

// CaseChecks runs every case of a file.
func CaseChecks(root, path string) []Result {
	cases, err := LoadCases(path)
	if err != nil {
		return []Result{fail(path, "(file)", "case-file", "%v", err)}
	}
	out := []Result{}
	seen := map[string]bool{}
	for _, c := range cases {
		if c.Name == "" || seen[c.Name] {
			out = append(out, fail(path, c.Name, "case", "a case needs a name of its own"))
			continue
		}
		seen[c.Name] = true
		out = append(out, res(path, c.Name, "case", RunCase(root, c)))
	}
	return out
}

// selectedCaseText exports an unevaluated selection of the imported source.
// It preserves the graph's existing context and appends case facts, as RunCase
// does. The CLI still validates and evaluates it in a separate process.
func selectedCaseText(text string, c Case) (string, error) {
	ResetEngineGlobals()
	cap := StartCapture()
	defer func() { cap.Stop(); ResetEngineGlobals() }()
	ag, err := importCase([]byte(text), c)
	if err != nil {
		return "", err
	}
	var out bytes.Buffer
	cyaml.Export(&out, ag)
	return out.String(), nil
}

// CaseRoundTrip evaluates a case with the carneades command, reads the YAML
// it writes back in a second process, and compares the labels (PLAN.md 4.5:
// export followed by import in a new process). The second run must also
// meet every label, argument and issue expectation; the first output must too.
func CaseRoundTrip(cli *CLI, root string, c Case) []string {
	var text string
	if c.Graph != "" {
		text = c.Graph
	} else {
		lib := c.Library
		if lib == "" {
			lib = "walton.yml"
		}
		data, err := os.ReadFile(filepath.Join(root, lib))
		if err != nil {
			return []string{err.Error()}
		}
		text = string(data)
	}
	// Always merge the context structurally. Appending another assumptions
	// or questioned YAML key would replace the graph's original context in
	// the CLI reader while RunCase correctly appends to that context.
	prepared, err := selectedCaseText(text, c)
	if err != nil {
		return []string{"case preparation: " + err.Error()}
	}
	text = prepared
	first := cli.Run(text, "eval", "-t", "yaml")
	if first.Exit != 0 {
		return []string{fmt.Sprintf("first run: exit %d: %s", first.Exit, firstLine(first.Stderr))}
	}
	second := cli.Run(first.Stdout, "eval", "-t", "yaml")
	if second.Exit != 0 {
		return []string{fmt.Sprintf("the second process cannot read the first one's YAML: exit %d: %s", second.Exit, firstLine(second.Stderr))}
	}
	l1, err1 := labels(first.Stdout)
	l2, err2 := labels(second.Stdout)
	if err1 != nil || err2 != nil {
		return []string{fmt.Sprintf("output is not YAML: %v %v", err1, err2)}
	}
	var probs []string
	// the exit criterion of PLAN.md Phase 4: the same theory, parameters,
	// expected labels, questioned statements and defaults, and the graph
	// read back passes validation
	var d1, d2 map[string]interface{}
	_ = yaml.Unmarshal([]byte(first.Stdout), &d1)
	_ = yaml.Unmarshal([]byte(second.Stdout), &d2)
	for _, k := range []string{"language", "argument_schemes", "issue_schemes", "weighing_functions", "tests", "questioned", "defaults", "assumptions"} {
		if !reflect.DeepEqual(d1[k], d2[k]) {
			probs = append(probs, k+" differs after the round trip")
		}
	}
	params := func(d map[string]interface{}) map[string]interface{} {
		out := map[string]interface{}{}
		if args, ok := d["arguments"].(map[interface{}]interface{}); ok {
			for id, a := range args {
				if m, ok := a.(map[interface{}]interface{}); ok {
					out[fmt.Sprint(id)] = m["parameters"]
				}
			}
		}
		return out
	}
	if !reflect.DeepEqual(params(d1), params(d2)) {
		probs = append(probs, "argument parameters differ after the round trip")
	}
	if r := cli.Run(first.Stdout, "check"); r.Exit != 0 {
		probs = append(probs, "the exported graph does not pass check: "+firstLine(r.Stderr))
	}
	for id, a := range l1 {
		if b, ok := l2[terms.Normalize(id)]; !ok {
			if b, ok = l2[id]; !ok {
				probs = append(probs, id+" is missing after the round trip")
				continue
			}
			if a != b {
				probs = append(probs, fmt.Sprintf("%s: %s, then %s", id, a, b))
			}
		} else if a != b {
			probs = append(probs, fmt.Sprintf("%s: %s, then %s", id, a, b))
		}
	}
	for _, run := range []struct{ name, text string }{
		{"first output", first.Stdout}, {"after the round trip", second.Stdout},
	} {
		observed, err := observeCaseYAML(run.text)
		if err != nil {
			probs = append(probs, run.name+": cannot read observations: "+err.Error())
			continue
		}
		for _, problem := range caseExpectationProblems(c, observed) {
			probs = append(probs, run.name+": "+problem)
		}
	}
	sort.Strings(probs)
	return probs
}

// CaseRoundTrips runs CaseRoundTrip for every case of a file that completes.
func CaseRoundTrips(cli *CLI, root, path string) []Result {
	cases, err := LoadCases(path)
	if err != nil {
		return nil // reported by CaseChecks
	}
	out := []Result{}
	for _, c := range cases {
		if c.Outcome != "" || c.Name == "" {
			continue
		}
		out = append(out, res(path, c.Name, "roundtrip", CaseRoundTrip(cli, root, c)))
	}
	return out
}
